import pandas as pd
import numpy as np

# Load all experiments
dfs = {}
for i in range(1, 6):
    dfs[i] = pd.read_csv(f"results_v6/batch20_qwen/bioreactor_titer_loss_v6_40505_data/experiment_{i}.csv")

# Print key columns and summary for each experiment
for eid, df in dfs.items():
    print(f"\n=== Experiment {eid} ===")
    # Find which columns look like interventions and outcomes
    cols = [c for c in df.columns if 'chelator' in c.lower() or 'flow' in c.lower() or 'titer' in c.lower() or 'turbid' in c.lower()]
    print(f"Relevant columns: {cols}")
    if cols:
        print(df[cols].describe())
        if len(cols) >= 2:
            print(f"Corr (titer vs others):")
            titer_col = [c for c in cols if 'titer' in c.lower()][0]
            for c in cols:
                if c != titer_col and df[c].nunique() > 1:
                    r = df[titer_col].corr(df[c])
                    print(f"  {titer_col} vs {c}: r={r:.3f}")
    else:
        print(df.head(3))
        print(df.describe().loc[['mean','std']])
